"""Regenerate Tauri icons at build time (icons are binary; this file is text-safe)."""
import base64, pathlib
ICONS = {
    "32x32.png": "",
    "128x128.png": "",
    "128x128@2x.png": "",
    "icon.ico": "",
    "icon.icns": "",
    "icon.png": "",
}

def main():
    d = pathlib.Path(__file__).resolve().parents[1] / 'app' / 'src-tauri' / 'icons'
    d.mkdir(parents=True, exist_ok=True)
    for name, b64 in ICONS.items():
        (d / name).write_bytes(base64.b64decode(b64))
    print(f'icons written to {d}')

if __name__ == "__main__":
    main()